import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Save, ArrowLeft, Plus, Trash2, AlertCircle, CheckCircle2, Archive } from 'lucide-react';
import { shopApi } from '../api/shop';
import { adminApi } from '../api/admin';
import { useShop } from '../context/ShopContext';
import { CatalogStatus } from '../types';
import ConfirmModal from '../components/ConfirmModal';

const BILLING_CYCLES = [
  { value: 'monthly', period: '/month', label: 'Monthly (/month)' },
  { value: 'quarterly', period: '/quarter', label: 'Quarterly (/quarter)' },
  { value: 'yearly', period: '/year', label: 'Yearly (/year)' },
] as const;

const SubscriptionEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { shopConfig, refreshAll } = useShop();
  const isEditing = Boolean(id);

  const [loading, setLoading] = useState(isEditing);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [slug, setSlug] = useState('');
  const [sku, setSku] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [originalPrice, setOriginalPrice] = useState('');
  const [billingCycle, setBillingCycle] = useState<'monthly' | 'quarterly' | 'yearly'>('monthly');
  const [domain, setDomain] = useState('saas');
  const [visibility, setVisibility] = useState<'hidden' | 'catalog' | 'search' | 'featured'>('catalog');
  const [status, setStatus] = useState<CatalogStatus>('draft');
  const [image, setImage] = useState('');
  const [maxSeats, setMaxSeats] = useState('1');
  const [licenseType, setLicenseType] = useState('Commercial');
  const [recommended, setRecommended] = useState(false);
  const [features, setFeatures] = useState<string[]>(['Full source access']);
  const [tagsText, setTagsText] = useState('');

  // Refund Policy
  const [refundAllowed, setRefundAllowed] = useState(false);
  const [fullRefund, setFullRefund] = useState(false);
  const [partialRefund, setPartialRefund] = useState(false);
  const [refundWindowHours, setRefundWindowHours] = useState('72');
  const [digitalAccessRevoked, setDigitalAccessRevoked] = useState(true);

  const [archiveModalOpen, setArchiveModalOpen] = useState(false);
  const [statusSaving, setStatusSaving] = useState(false);

  const activeCurrency = shopConfig.currency || 'IRR';

  useEffect(() => {
    if (!id) return;
    let mounted = true;
    const loadPlan = async () => {
      setLoading(true);
      setError(null);
      try {
        const plan = await shopApi.getSubscription(id);
        if (!mounted) return;
        if (!plan) {
          setError('Subscription plan not found.');
          return;
        }
        setName(plan.title || '');
        setSubtitle(plan.subtitle || '');
        setSlug(plan.slug || '');
        setSku(plan.sku || '');
        setDescription(plan.description || '');
        setPrice(plan.price ? String(plan.price) : '');
        setOriginalPrice(plan.originalPrice ? String(plan.originalPrice) : '');
        const resolvedCycle =
          plan.billingCycle ||
          (plan.period === '/quarter' ? 'quarterly' : plan.period === '/year' ? 'yearly' : 'monthly');
        setBillingCycle(resolvedCycle);
        setDomain(plan.domain || 'saas');
        setVisibility(plan.visibility || 'catalog');
        if (plan.status) setStatus(plan.status);
        setImage(plan.image || '');
        setMaxSeats(String(plan.maxSeats || plan.maxUsers || 1));
        setLicenseType(plan.licenseType || 'Commercial');
        setRecommended(Boolean(plan.recommended));
        setFeatures(plan.features && plan.features.length > 0 ? plan.features : ['Full source access']);
        setTagsText((plan.tags || []).join(', '));
        if (plan.refundPolicy) {
          setRefundAllowed(Boolean(plan.refundPolicy.allowed));
          setFullRefund(Boolean(plan.refundPolicy.fullRefund));
          setPartialRefund(Boolean(plan.refundPolicy.partialRefund));
          setRefundWindowHours(String(plan.refundPolicy.refundWindowHours ?? 72));
          setDigitalAccessRevoked(plan.refundPolicy.digitalAccessRevoked ?? true);
        }
      } catch (err: any) {
        if (mounted) setError(err?.error || err?.message || 'Failed to load plan.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    loadPlan();
    return () => {
      mounted = false;
    };
  }, [id]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setNotice(null);

    const parsedPrice = Math.round(Number(price));
    if (!name.trim() || name.trim().length < 3) {
      setError('Plan name must be at least 3 characters.');
      return;
    }
    if (!description.trim() || description.trim().length < 10) {
      setError('Description must be between 10 and 5,000 characters.');
      return;
    }
    if (!Number.isInteger(parsedPrice) || parsedPrice <= 0) {
      setError(`Price must be a positive integer in ${activeCurrency}.`);
      return;
    }

    const cleanedFeatures = features.map(f => f.trim()).filter(Boolean);
    if (cleanedFeatures.length === 0) {
      setError('At least one feature is required for a subscription plan.');
      return;
    }

    const cycleObj = BILLING_CYCLES.find(c => c.value === billingCycle) || BILLING_CYCLES[0];

    const payload: Record<string, any> = {
      name: name.trim(),
      title: name.trim(),
      description: description.trim(),
      price: parsedPrice,
      currency: activeCurrency,
      billingCycle: cycleObj.value,
      period: cycleObj.period,
      features: cleanedFeatures,
      recommended,
      autoRenew: false,
      trialDays: 0,
      domain,
      visibility,
    };

    if (subtitle.trim()) payload.subtitle = subtitle.trim();
    if (slug.trim()) payload.slug = slug.trim().toLowerCase();
    if (sku.trim()) payload.sku = sku.trim();
    if (originalPrice.trim()) {
      const parsedOrig = Math.round(Number(originalPrice));
      if (!Number.isInteger(parsedOrig) || parsedOrig < parsedPrice) {
        setError('Original price must be an integer greater than or equal to price.');
        return;
      }
      payload.originalPrice = parsedOrig;
    }
    if (image.trim()) payload.image = image.trim();
    const parsedSeats = Math.round(Number(maxSeats));
    if (Number.isInteger(parsedSeats) && parsedSeats >= 1) {
      payload.maxSeats = parsedSeats;
      payload.maxUsers = parsedSeats;
    }
    if (licenseType.trim()) payload.licenseType = licenseType.trim();
    const parsedTags = tagsText.split(',').map(t => t.trim()).filter(Boolean);
    if (parsedTags.length > 0) payload.tags = parsedTags;

    if (refundAllowed) {
      if (!fullRefund && !partialRefund) {
        setError('When refunds are allowed, enable at least Full Refund or Partial Refund.');
        return;
      }
      payload.refundPolicy = {
        allowed: true,
        storeCredit: true,
        fullRefund,
        partialRefund,
        refundWindowHours: Math.max(0, Math.min(87600, Math.round(Number(refundWindowHours) || 0))),
        digitalAccessRevoked,
      };
    } else {
      payload.refundPolicy = { allowed: false };
    }

    setSubmitting(true);
    try {
      if (isEditing && id) {
        await shopApi.updateSubscription(id, payload);
        setNotice('Subscription plan updated successfully.');
      } else {
        const res = await shopApi.createSubscription(payload);
        const createdId = res?.subscription?._id || res?.subscription?.id;
        await refreshAll();
        if (createdId) {
          navigate(`/admin/subscription/edit/${createdId}`, { replace: true });
          return;
        }
        setNotice('Subscription plan created as draft.');
      }
      await refreshAll();
    } catch (err: any) {
      const detailMsg = Array.isArray(err?.details) && err.details.length > 0
        ? err.details.map((d: any) => `${d.field || 'field'}: ${d.message}`).join('; ')
        : null;
      setError(detailMsg || err?.error || err?.message || 'Failed to save subscription plan.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleStatusChange = async (nextStatus: CatalogStatus) => {
    if (!id) return;
    setStatusSaving(true);
    setError(null);
    setNotice(null);
    try {
      await adminApi.updateCatalogStatus('subscription', id, nextStatus);
      setStatus(nextStatus);
      setNotice(`Plan status updated to ${nextStatus}.`);
      await refreshAll();
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not update plan status.');
    } finally {
      setStatusSaving(false);
    }
  };

  const handleArchive = async () => {
    if (!id) return;
    setArchiveModalOpen(false);
    setError(null);
    try {
      await shopApi.deleteSubscription(id);
      await refreshAll();
      navigate('/creator/catalog');
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to archive plan.');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-28 pb-16 px-4 text-center text-sm text-slate-500">
        Loading subscription plan...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pt-24 pb-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => navigate('/creator/catalog')}
              className="p-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-slate-600 dark:text-slate-300 hover:border-slate-400"
            >
              <ArrowLeft size={16} />
            </button>
            <div>
              <h1 className="text-2xl font-extrabold text-slate-900 dark:text-white tracking-tight">
                {isEditing ? 'Edit Subscription Plan' : 'New Subscription Plan'}
              </h1>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                Fixed-term fixed-price plans in {activeCurrency}. Auto-renewal and trials are disabled by platform policy.
              </p>
            </div>
          </div>

          {isEditing && (
            <div className="flex items-center gap-2">
              <select
                value={status}
                disabled={statusSaving}
                onChange={e => handleStatusChange(e.target.value as CatalogStatus)}
                aria-label="Lifecycle Status"
                className="px-3 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-mono font-semibold text-slate-800 dark:text-slate-200"
              >
                <option value="draft">draft</option>
                <option value="review">review</option>
                <option value="published">published</option>
                <option value="out_of_stock">out_of_stock</option>
                <option value="backorder">backorder</option>
                <option value="archived">archived</option>
                <option value="discontinued">discontinued</option>
              </select>
              <button
                type="button"
                onClick={() => setArchiveModalOpen(true)}
                className="px-3 py-2 rounded-lg border border-rose-500/30 bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-semibold inline-flex items-center gap-1.5"
              >
                <Archive size={14} />
                <span>Archive</span>
              </button>
            </div>
          )}
        </div>

        {error && (
          <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
            <AlertCircle size={15} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {notice && (
          <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
            <CheckCircle2 size={15} className="shrink-0" />
            <span>{notice}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl p-6 sm:p-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Plan Name * (3–200 chars)
              </label>
              <input
                type="text"
                required
                minLength={3}
                maxLength={200}
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="e.g. Enterprise Institutional Desk"
                className="w-full px-3.5 py-2.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Subtitle
              </label>
              <input
                type="text"
                maxLength={240}
                value={subtitle}
                onChange={e => setSubtitle(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                URL Slug
              </label>
              <input
                type="text"
                value={slug}
                onChange={e => setSlug(e.target.value)}
                placeholder="auto-generated if omitted"
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Price ({activeCurrency}) *
              </label>
              <input
                type="number"
                required
                min={1}
                step={1}
                value={price}
                onChange={e => setPrice(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono tabular-nums text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Original Price ({activeCurrency})
              </label>
              <input
                type="number"
                min={1}
                step={1}
                value={originalPrice}
                onChange={e => setOriginalPrice(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono tabular-nums text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Billing Cycle *
              </label>
              <select
                value={billingCycle}
                onChange={e => setBillingCycle(e.target.value as any)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              >
                {BILLING_CYCLES.map(c => (
                  <option key={c.value} value={c.value}>
                    {c.label}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Max Seats / Users
              </label>
              <input
                type="number"
                min={1}
                step={1}
                value={maxSeats}
                onChange={e => setMaxSeats(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono tabular-nums text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                License Type
              </label>
              <input
                type="text"
                maxLength={200}
                value={licenseType}
                onChange={e => setLicenseType(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                SKU
              </label>
              <input
                type="text"
                maxLength={120}
                value={sku}
                onChange={e => setSku(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Domain
              </label>
              <select
                value={domain}
                onChange={e => setDomain(e.target.value)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              >
                <option value="fintech">fintech</option>
                <option value="saas">saas</option>
                <option value="commerce">commerce</option>
                <option value="frontend">frontend</option>
                <option value="software">software</option>
                <option value="other">other</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Visibility
              </label>
              <select
                value={visibility}
                onChange={e => setVisibility(e.target.value as any)}
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              >
                <option value="catalog">catalog</option>
                <option value="search">search</option>
                <option value="featured">featured</option>
                <option value="hidden">hidden</option>
              </select>
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Cover Image URI
              </label>
              <input
                type="url"
                value={image}
                onChange={e => setImage(e.target.value)}
                placeholder="https://..."
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm font-mono text-slate-900 dark:text-white"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Description * (10–5,000 chars)
              </label>
              <textarea
                required
                minLength={10}
                maxLength={5000}
                rows={4}
                value={description}
                onChange={e => setDescription(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                Tags (comma separated)
              </label>
              <input
                type="text"
                value={tagsText}
                onChange={e => setTagsText(e.target.value)}
                placeholder="enterprise, support, mt5"
                className="w-full px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
              />
            </div>
          </div>

          {/* Recommended Checkbox */}
          <label className="flex items-center gap-2.5 text-xs font-semibold text-slate-700 dark:text-slate-300">
            <input
              type="checkbox"
              checked={recommended}
              onChange={e => setRecommended(e.target.checked)}
              className="rounded border-slate-300 accent-emerald-600"
            />
            <span>Mark as Recommended Tier</span>
          </label>

          {/* Features */}
          <div className="space-y-3 pt-4 border-t border-[#E4E4DE] dark:border-[#222630]">
            <div className="flex items-center justify-between">
              <label className="text-xs font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
                Included Plan Features *
              </label>
              <button
                type="button"
                onClick={() => setFeatures(prev => [...prev, ''])}
                className="text-xs font-semibold text-emerald-600 dark:text-emerald-400 inline-flex items-center gap-1"
              >
                <Plus size={14} /> Add Feature
              </button>
            </div>
            <div className="space-y-2">
              {features.map((feat, idx) => (
                <div key={idx} className="flex gap-2">
                  <input
                    type="text"
                    value={feat}
                    onChange={e => {
                      const next = [...features];
                      next[idx] = e.target.value;
                      setFeatures(next);
                    }}
                    placeholder="e.g. Dedicated Quant Desk SLA"
                    className="flex-1 px-3.5 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#090A0D] text-sm text-slate-900 dark:text-white"
                  />
                  {features.length > 1 && (
                    <button
                      type="button"
                      onClick={() => setFeatures(prev => prev.filter((_, i) => i !== idx))}
                      className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-lg"
                    >
                      <Trash2 size={15} />
                    </button>
                  )}
                </div>
              ))}
            </div>
          </div>

          {/* Refund Policy */}
          <div className="space-y-3 pt-4 border-t border-[#E4E4DE] dark:border-[#222630]">
            <label className="flex items-center gap-2.5 text-xs font-bold text-slate-700 dark:text-slate-300">
              <input
                type="checkbox"
                checked={refundAllowed}
                onChange={e => setRefundAllowed(e.target.checked)}
                className="rounded border-slate-300 accent-emerald-600"
              />
              <span>Allow Store-Credit Refunds</span>
            </label>

            {refundAllowed && (
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 p-4 rounded-xl bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630]">
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={fullRefund}
                    onChange={e => setFullRefund(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Full Refund</span>
                </label>
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={partialRefund}
                    onChange={e => setPartialRefund(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Partial Refund</span>
                </label>
                <label className="flex items-center gap-2 text-xs text-slate-700 dark:text-slate-300">
                  <input
                    type="checkbox"
                    checked={digitalAccessRevoked}
                    onChange={e => setDigitalAccessRevoked(e.target.checked)}
                    className="accent-emerald-600"
                  />
                  <span>Revoke Access on Full Refund</span>
                </label>
                <div className="sm:col-span-3">
                  <label className="block text-[11px] text-slate-500 mb-1">
                    Refund Window Hours (0 = unlimited, max 87,600)
                  </label>
                  <input
                    type="number"
                    min={0}
                    max={87600}
                    value={refundWindowHours}
                    onChange={e => setRefundWindowHours(e.target.value)}
                    className="w-40 px-3 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-mono text-slate-900 dark:text-white"
                  />
                </div>
              </div>
            )}
          </div>

          <div className="pt-4 border-t border-[#E4E4DE] dark:border-[#222630] flex justify-end gap-3">
            <button
              type="button"
              onClick={() => navigate('/creator/catalog')}
              className="px-4 py-2.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] text-xs font-semibold text-slate-700 dark:text-slate-300"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="px-5 py-2.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 disabled:opacity-50 text-white text-xs font-bold inline-flex items-center gap-2"
            >
              <Save size={15} />
              <span>{submitting ? 'Saving...' : isEditing ? 'Update Plan' : 'Create Plan Draft'}</span>
            </button>
          </div>
        </form>
      </div>

      <ConfirmModal
        isOpen={archiveModalOpen}
        onClose={() => setArchiveModalOpen(false)}
        onConfirm={handleArchive}
        title="Archive Subscription Plan"
        message={`Archive "${name}"? Existing subscribers retain their entitlement history, while new purchases are disabled.`}
        confirmText="Archive Plan"
        variant="warning"
      />
    </div>
  );
};

export default SubscriptionEditor;
